import React, { useState, useEffect } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { FiEye, FiEyeOff, FiMail, FiLock, FiAlertCircle, FiCheckCircle, FiArrowLeft } from 'react-icons/fi';
import axios from 'axios';
import { useAdminData } from '../context/AdminContext';

const Login = () => {
  const navigate = useNavigate();
  const { refreshAdminData } = useAdminData();

  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPwd, setShowPwd] = useState(false);
  const [remember, setRemember] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  // ── Si déjà connecté → redirect ──────────────────────────────────────────
  useEffect(() => {
    const token = localStorage.getItem('token');
    const user = localStorage.getItem('user');
    if (token && user) {
      try {
        const u = JSON.parse(user);
        if (u.role === 'admin') navigate('/administration/Dashboard', { replace: true });
        if (u.role === 'coach') navigate('/coach/Dashboard', { replace: true });
        if (u.role === 'player') navigate('/players', { replace: true });
      } catch { }
    }
  }, [navigate]);

  // ── Submit ────────────────────────────────────────────────────────────────
  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setSuccess('');

    if (!email || !password) { setError('Please fill in all fields'); return; }

    const emailRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRe.test(email)) { setError('Please enter a valid email address'); return; }

    setIsLoading(true);
    try {
      const res = await axios.post('http://localhost:8000/api/login/', { email, password });
      const { token, user: userData } = res.data;

      if (!userData) { setError('Login successful but user data missing'); return; }

      // Sauvegarde
      localStorage.setItem('token', token);
      localStorage.setItem('user', JSON.stringify(userData));
      localStorage.setItem('role', userData.role);
      localStorage.setItem('academy_id', userData.academy_id);

      // Remember me
      if (remember) localStorage.setItem('remember_email', email);
      else localStorage.removeItem('remember_email');

      setSuccess('Login successful! Redirecting...');
      setEmail('');
      setPassword('');

      setTimeout(async () => {
        if (userData.role === 'admin') {
          await refreshAdminData();
          navigate('/administration/Dashboard', { replace: true });
        } else if (userData.role === 'coach') {
          navigate('/coach/Dashboard', { replace: true });
        } else {
          navigate('/players', { replace: true });
        }
      }, 800);

    } catch (err) {
      const msg = err.response?.data?.error || err.response?.data?.detail || 'Login failed. Please try again.';
      setError(msg);
    } finally {
      setIsLoading(false);
    }
  };

  // ── Remember me — pré-remplir email ──────────────────────────────────────
  useEffect(() => {
    const saved = localStorage.getItem('remember_email');
    if (saved) { setEmail(saved); setRemember(true); }
  }, []);

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-950 via-blue-950 to-purple-900 text-gray-100 flex items-center justify-center relative overflow-hidden">
      {/* Decorative bg matching Signup */}
      <div className="absolute inset-0 overflow-hidden">
        <div className="absolute w-[500px] h-[500px] bg-gradient-to-r from-blue-600/20 to-purple-600/20 rounded-full -top-40 -left-40 animate-pulse"></div>
        <div className="absolute w-[600px] h-[600px] bg-gradient-to-br from-blue-800/10 to-purple-800/10 rounded-full -bottom-60 -right-60 rotate-45"></div>
      </div>

      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.8 }}
        className="w-full max-w-2xl space-y-8 relative z-10 px-4 py-12"
      >
        {/* Back to Home Link - Now aligned inside container */}
        <div className="flex">
          <Link 
            to="/" 
            className="inline-flex items-center gap-2 text-gray-400 hover:text-blue-400 transition-all duration-300 group"
          >
            <FiArrowLeft className="group-hover:-translate-x-1.5 transition-transform duration-300" />
            <span className="font-medium">Back to Home</span>
          </Link>
        </div>

        {/* Brand Header matching Signup */}
        <div className="text-center space-y-3">
          <motion.h1
            initial={{ scale: 0.95 }}
            animate={{ scale: 1 }}
            className="text-4xl font-bold bg-gradient-to-r from-blue-400 to-purple-300 bg-clip-text text-transparent"
          >
            Welcome to RUNAINI
          </motion.h1>
          <p className="text-gray-400 text-lg">
            Don't have an account?{' '}
            <Link to="/signup" className="text-blue-400 hover:text-blue-300 font-medium transition-colors">
              Sign up Now
            </Link>
          </p>
        </div>

        {/* Card matching Signup sections */}
        <div className="space-y-8 bg-gray-900/40 backdrop-blur-xl p-8 rounded-3xl border border-gray-800/60 shadow-2xl">
          <AnimatePresence mode="wait">
            {error && (
              <motion.div
                initial={{ opacity: 0, y: -10 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -10 }}
                className="p-4 bg-red-900/50 border border-red-700/60 rounded-xl text-red-300 flex items-center gap-3"
              >
                <FiAlertCircle className="shrink-0" />
                {error}
              </motion.div>
            )}
            {success && (
              <motion.div
                initial={{ opacity: 0, y: -10 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -10 }}
                className="p-4 bg-green-900/50 border border-green-700/60 rounded-xl text-green-300 flex items-center gap-3"
              >
                <FiCheckCircle className="shrink-0" />
                {success}
              </motion.div>
            )}
          </AnimatePresence>

          <form onSubmit={handleSubmit} className="space-y-6">
            <div className="space-y-6">
              <h3 className="text-xl font-semibold text-blue-200 border-l-4 border-blue-500 pl-3">
                Login Credentials
              </h3>
              
              <div className="space-y-5">
                {/* Email Field */}
                <motion.div whileHover={{ y: -2 }}>
                  <label className="block text-sm font-medium mb-2">Email Address<span className="text-red-400">*</span></label>
                  <div className="relative">
                    <input 
                      type="email" 
                      value={email} 
                      onChange={e => { setEmail(e.target.value); setError(''); }}
                      className="w-full px-4 py-3.5 bg-gray-800/40 border border-gray-700/60 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                      placeholder="your.email@example.com" 
                      required 
                      autoComplete="email"
                    />
                  </div>
                </motion.div>

                {/* Password Field */}
                <motion.div whileHover={{ y: -2 }}>
                  <div className="flex items-center justify-between mb-2">
                    <label className="block text-sm font-medium">Password<span className="text-red-400">*</span></label>
                    <Link to="/forgot-password" size="sm" className="text-xs text-blue-400 hover:text-blue-300 transition-colors">
                      Forgot password?
                    </Link>
                  </div>
                  <div className="relative">
                    <input 
                      type={showPwd ? 'text' : 'password'} 
                      value={password} 
                      onChange={e => { setPassword(e.target.value); setError(''); }}
                      className="w-full px-4 py-3.5 bg-gray-800/40 border border-gray-700/60 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all pr-12"
                      placeholder="Enter your password" 
                      required 
                      autoComplete="current-password"
                    />
                    <button 
                      type="button" 
                      onClick={() => setShowPwd(!showPwd)}
                      className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-500 hover:text-gray-300 transition-colors"
                    >
                      {showPwd ? <FiEyeOff size={18} /> : <FiEye size={18} />}
                    </button>
                  </div>
                </motion.div>
              </div>
            </div>

            {/* Remember and Submit */}
            <div className="space-y-6 mt-8">
              <div className="flex items-center gap-2">
                <input 
                  type="checkbox" 
                  id="remember" 
                  checked={remember}
                  onChange={e => setRemember(e.target.checked)}
                  className="w-4 h-4 rounded bg-gray-800 border-gray-700 text-blue-600 focus:ring-blue-500 focus:ring-offset-gray-900" 
                />
                <label htmlFor="remember" className="text-sm text-gray-400 cursor-pointer select-none">
                  Remember me for 30 days
                </label>
              </div>

              <motion.button
                whileHover={{ scale: 1.02 }}
                whileTap={{ scale: 0.98 }}
                disabled={isLoading}
                type="submit"
                className="w-full bg-gradient-to-r from-blue-600 to-purple-600 py-4 rounded-xl font-medium text-lg hover:shadow-lg hover:shadow-blue-500/20 transition-all disabled:opacity-70 disabled:cursor-not-allowed flex items-center justify-center gap-2"
              >
                {isLoading ? (
                  <>
                    <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                    Signing in...
                  </>
                ) : 'Sign In'}
              </motion.button>
            </div>
          </form>
        </div>

        {/* Footer matching Signup style */}
        <p className="text-center text-xs text-gray-500 mt-8 uppercase tracking-widest">
          © {new Date().getFullYear()} RunAiNi · Football Academy Management Platform
        </p>
      </motion.div>
    </div>
  );
};

export default Login;